import numpy as np
from scipy.optimize import minimize_scalar
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
one=np.ones_like(t)
cands={
 'exp(-t)':np.exp(-t),'t*exp(-t)':t*np.exp(-t),'t':t,'t^2':t**2,'sqrt t':np.sqrt(t),'log t':np.log(t),
 'exp(-t/2)':np.exp(-t/2),'1/(1+t)':1/(1+t),'exp(-0.5t)*t':t*np.exp(-0.5*t),'sin(t)':np.sin(t),'cos(t)':np.cos(t),
 'exp(t/12)':np.exp(t/12),'t/(1+t)':t/(1+t),'exp(-2t)':np.exp(-2*t),'exp(-t^2)':np.exp(-t**2),'t*exp(-t^2)':t*np.exp(-t**2),
}
out=[]
for name,g in cands.items():
    def f(w):
        s=np.sin(w*t); c=np.cos(w*t)
        X=np.column_stack([np.sqrt(P),P*s,one,g,c])
        cf=np.linalg.lstsq(X,y,rcond=None)[0]
        return np.mean((y-X@cf)**2)/np.var(y)
    r=minimize_scalar(f,bounds=(0.3,0.6),method='bounded',options={'xatol':1e-10})
    out.append((r.fun,name,r.x))
for o in sorted(out)[:8]: print(o)

